examples.bad:
final readonly class RoomAvailabilityReader
{
    public function __construct(private AvailabilityCache $cache, private Rooms $rooms) {}

    /** @return array{rooms: list<Room>, canBook: bool} */
    public function for(Guest $guest, Stay $stay): array
    {
        $key = 'availability.'.$stay->id;
        $entry = $this->cache->get($key);

        if ($entry === null) {
            // one shared entry per stay, but it holds a per-guest flag
            $entry = ['rooms' => $this->rooms->availableFor($stay), 'canBook' => $guest->isVerified()];
            $this->cache->set($key, $entry, 300);
        }

        return $entry;
    }
}

examples.good:
final readonly class RoomAvailabilityReader
{
    public function __construct(private AvailabilityCache $cache, private Rooms $rooms) {}

    /** @return array{rooms: list<Room>, canBook: bool} */
    public function for(Guest $guest, Stay $stay): array
    {
        $key = 'availability.'.$stay->id;
        $rooms = $this->cache->get($key);

        if ($rooms === null) {
            $rooms = $this->rooms->availableFor($stay);
            $this->cache->set($key, $rooms, 300);
        }

        // Resolved after the lookup: the verdict differs per guest, and a shared entry would leak it.
        return ['rooms' => $rooms, 'canBook' => $guest->isVerified()];
    }
}

