examples.bad:
final readonly class ReservationConfirmedListener
{
    public function __construct(private Invoices $invoices, private Mailer $mailer) {}

    public function __invoke(ReservationConfirmed $event): void
    {
        // business rule inside the listener, and a retry sends a second invoice
        $total = $event->nights * $event->nightlyRate;
        if ($event->guestIsMember) {
            $total = (int) ($total * 0.9);
        }
        $this->invoices->save(new Invoice($event->reservationId, $total));
        $this->mailer->send($event->guestEmail, 'Your invoice');
    }
}

examples.good:
final readonly class ReservationConfirmedListener
{
    public function __construct(private CommandBus $commands) {}

    public function __invoke(ReservationConfirmed $event): void
    {
        // the handler holds the pricing rule and skips an invoice that already exists
        $this->commands->dispatch(new IssueInvoice($event->reservationId));
    }
}

final readonly class IssueInvoiceHandler
{
    public function __construct(private Invoices $invoices) {}

    public function __invoke(IssueInvoice $command): void
    {
        if ($this->invoices->existsFor($command->reservationId)) {
            return;
        }
        $this->invoices->issueFor($command->reservationId);
    }
}

