public static function cancellable(): iterable
{
    yield 'pending' => [Reservation::pending()];
    yield 'confirmed' => [Reservation::confirmed()];
}

public static function notCancellable(): iterable
{
    yield 'cancelled' => [Reservation::cancelled()];
    yield 'checked out' => [Reservation::checkedOut()];
}

